(()=>{'use strict';
const API='https://woongbi-quote-api.woongbts.workers.dev/quote/mobile';
const ids=['carrier','join-type','discount-method','device-select','plan-select','installment-months','welfare-type'];
let timer=0,seq=0,lastPair={support:null,contract:null},lastState=null;
const cache=new Map(),pending=new Map();
const $=id=>document.getElementById(id);
const won=v=>Number.isFinite(Number(v))?Math.max(0,Math.round(Number(v))).toLocaleString('ko-KR')+'원':'—';
const text=(id,value)=>{const node=$(id);if(node&&node.textContent!==String(value))node.textContent=String(value)};
function currentState(){const device=$('device-select')?.value||'',plan=$('plan-select')?.value||'',join=$('join-type')?.value||'',method=$('discount-method')?.value||'support',months=Number($('installment-months')?.value||24),welfare=$('welfare-type')?.value||'none';return{device_id:device,plan_id:plan,join_type:join,method,months,welfare_type:welfare}}
function normalize(input={}){return{device_id:String(input.device_id??input.device??''),plan_id:String(input.plan_id??input.plan??''),join_type:String(input.join_type??input.join??''),method:String(input.method||'support'),months:Number(input.months||24),welfare_type:String(input.welfare_type??input.welfare??'none')}}
function keyOf(input){const s=normalize(input);return[s.device_id,s.plan_id,s.join_type,s.method,s.months,s.welfare_type].join('|')}
async function fetchQuote(input){const s=normalize(input),key=keyOf(s);if(!s.device_id||!s.plan_id||!s.join_type)return null;if(cache.has(key))return cache.get(key);if(pending.has(key))return pending.get(key);const task=(async()=>{const response=await fetch(API,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(s)});if(!response.ok)throw Error('quote-api-'+response.status);const data=await response.json();if(!data||data.ok!==true)throw Error('quote-api-invalid');cache.set(key,data.quote);if(cache.size>120)cache.delete(cache.keys().next().value);return data.quote})().finally(()=>pending.delete(key));pending.set(key,task);return task}
function get(input){return cache.get(keyOf(input))??null}
function getCurrent(method){const s=currentState();return get({...s,method:method||s.method})}
async function quotePair(input={}){const s=normalize({...currentState(),...input});const [a,b]=await Promise.allSettled([fetchQuote({...s,method:'support'}),fetchQuote({...s,method:'contract'})]);return{support:a.status==='fulfilled'?a.value:null,contract:b.status==='fulfilled'?b.value:null,supportError:a.status==='rejected',contractError:b.status==='rejected'}}
function clearMoney(){['principal','device-monthly','installment-fee','service-monthly','monthly-total','mobile-quote-bar-total','explain-price','explain-device-discount','explain-principal','explain-interest','explain-device-monthly','explain-plan-fee','explain-contract-discount','explain-welfare','explain-service','explain-monthly-total'].forEach(id=>text(id,'—'));text('welfare-view','미적용');const bar=$('mobile-quote-bar');if(bar)bar.hidden=true;document.body.classList.remove('has-mobile-quote-bar')}
function applyLoading(){clearMoney();text('compare-support-monthly','—');text('compare-support-benefit','지원금 —');text('compare-contract-monthly','—');text('compare-contract-benefit','월 할인 —');text('compare-best','계산 중');text('compare-diff','선택한 조건의 견적을 불러오고 있습니다.');text('calc-summary','선택한 조건의 견적을 불러오고 있습니다.');text('explain-note','서버에서 현재 조건을 확인하고 있습니다.')}
function applyUnavailable(){clearMoney();text('discount-amount-view','—');text('plan-discount-view','—');text('compare-support-monthly','—');text('compare-support-benefit','지원금 —');text('compare-contract-monthly','—');text('compare-contract-benefit','월 할인 —');text('compare-best','자동 계산 확인 필요');text('compare-diff','현재 자동 계산을 불러오지 못했습니다. 상담으로 확인해 주세요.');text('calc-summary','현재 자동 계산을 불러오지 못했습니다. 상담으로 확인해 주세요.');text('mobile-data-note','현재 자동 계산을 불러오지 못했습니다. 잠시 후 다시 시도하거나 상담으로 확인해 주세요.');text('explain-note','현재 자동 계산을 불러오지 못해 상담에서 최종 확인이 필요합니다.')}
function applyBase(q,s){if(!q?.known)return;text('device-price-view',won(q.price));text('plan-fee-view',won(q.planFee));text('explain-price',won(q.price));text('explain-plan-fee',won(q.planFee));text('discount-amount-label',s.method==='contract'?'선택약정 월 할인':'공시지원금');text('principal-label',s.method==='contract'?'단말 할부원금':'공시지원 반영 할부원금');text('plan-discount-label',s.method==='contract'?'선택약정 할인':'요금 할인');text('extra-support-view','매장 문의')}
function applyCurrent(q,s){if(!q?.known)return false;applyBase(q,s);if(s.method==='contract'){text('discount-amount-view','-'+won(q.contractDiscount));text('plan-discount-view','-'+won(q.contractDiscount));text('mobile-data-note','선택약정 25% 조건을 서버에서 계산해 반영했습니다.')}else{text('discount-amount-view',won(q.support));text('plan-discount-view','미적용');text('mobile-data-note','현재 등록된 공시지원금을 선택한 조건에 맞춰 서버에서 반영했습니다.')}text('principal',won(q.principal));text('device-monthly',won(q.inst?.monthly));text('installment-fee',won(q.inst?.fee));text('service-monthly',won(q.service));text('monthly-total',won(q.monthly));text('welfare-view',q.welfare?.amount?`${q.welfare.label||'복지할인'} -${won(q.welfare.amount)}`:'미적용');text('explain-device-discount',s.method==='support'&&q.support?'-'+won(q.support):'미적용');text('explain-principal',won(q.principal));text('explain-interest',won(q.inst?.fee));text('explain-device-monthly',won(q.inst?.monthly));text('explain-contract-discount',s.method==='contract'&&q.contractDiscount?'-'+won(q.contractDiscount):'미적용');text('explain-welfare',q.welfare?.amount?'-'+won(q.welfare.amount):'미적용');text('explain-service',won(q.service));text('explain-monthly-total',won(q.monthly));text('explain-note',`월 단말금 ${won(q.inst?.monthly)} + 월 통신요금 ${won(q.service)} = 예상 월 납부액 ${won(q.monthly)}입니다. 추가지원금·실시간 프로모션은 포함하지 않습니다.`);text('calc-summary',`${$('carrier')?.value||''} · ${$('device-select')?.selectedOptions?.[0]?.textContent||''} · ${$('join-type')?.value||''} · ${$('plan-select')?.selectedOptions?.[0]?.textContent||''} · ${s.method==='contract'?'선택약정':'공시지원'} · ${s.months}개월 기준 예상치입니다.`);const panelActive=document.querySelector('[data-panel="mobile"]')?.classList.contains('active'),directVisible=!$('direct-mobile-grid')?.hidden,bar=$('mobile-quote-bar');if(bar){const show=Boolean(panelActive&&directVisible);bar.hidden=!show;document.body.classList.toggle('has-mobile-quote-bar',show);if(show)text('mobile-quote-bar-total',won(q.monthly))}return true}
function applyUnknownSupport(contract){if(contract?.known){text('device-price-view',won(contract.price));text('plan-fee-view',won(contract.planFee));text('explain-price',won(contract.price));text('explain-plan-fee',won(contract.planFee))}text('discount-amount-view','매장 확인');text('plan-discount-view','미적용');['principal','device-monthly','installment-fee','service-monthly','monthly-total'].forEach(id=>text(id,'—'));text('welfare-view','미적용');text('calc-summary','이 가입유형·기종·요금제의 공시지원금은 매장에서 최신 금액을 확인해 주세요.');text('mobile-data-note','공시지원금은 매장에서 최신 금액을 확인해 주세요. 선택약정 금액은 비교 영역에서 확인할 수 있습니다.');text('explain-note','공시지원금 확인이 필요한 조건입니다. 확인된 금액만 계산에 반영합니다.');const bar=$('mobile-quote-bar');if(bar)bar.hidden=true;document.body.classList.remove('has-mobile-quote-bar')}
function applyCompare(support,contract){if(support?.known){text('compare-support-monthly',won(support.monthly));text('compare-support-benefit',`공시지원금 ${won(support.support)}`)}else if(support&&support.known===false){text('compare-support-monthly','매장 확인');text('compare-support-benefit','지원금 —')}else{text('compare-support-monthly','—');text('compare-support-benefit','지원금 —')}if(contract?.known){text('compare-contract-monthly',won(contract.monthly));text('compare-contract-benefit',`월 선택약정 할인 ${won(contract.contractDiscount)}`)}else{text('compare-contract-monthly','—');text('compare-contract-benefit','월 할인 —')}if(support?.known&&contract?.known){const diff=Math.abs(Number(support.total24)-Number(contract.total24));const best=Number(support.total24)<=Number(contract.total24)?'공시지원금':'선택약정';text('compare-best',diff<500?'두 방식이 비슷해요':`${best} 쪽이 유리`);text('compare-diff',diff<500?'현재 조건에서는 두 방식의 전체 부담 차이가 크지 않습니다.':`${best} 쪽이 전체 부담 기준으로 더 유리합니다.`)}else if(contract?.known&&support&&support.known===false){text('compare-best','공시지원금 확인 필요');text('compare-diff','선택약정은 계산됐고, 공시지원금은 매장에서 최신 금액을 확인해 비교해 드립니다.')}else{text('compare-best','조건을 확인해 주세요');text('compare-diff','현재 조건의 견적을 모두 불러오지 못했습니다.')}}
async function sync(){const s=currentState();lastState=s;if(!s.device_id||!s.plan_id||!s.join_type){clearMoney();document.documentElement.dataset.quoteApi='idle';return null}const run=++seq;applyLoading();const pair=await quotePair(s);if(run!==seq)return null;lastPair=pair;applyCompare(pair.support,pair.contract);const selectedError=s.method==='contract'?pair.contractError:pair.supportError,current=s.method==='contract'?pair.contract:pair.support;if(selectedError){applyUnavailable();document.documentElement.dataset.quoteApi='unavailable';window.dispatchEvent(new CustomEvent('woongbi:quote-unavailable',{detail:{state:s,pair}}));return{state:s,pair,current:null}}if(current?.known)applyCurrent(current,s);else if(s.method==='support'&&pair.support&&pair.support.known===false)applyUnknownSupport(pair.contract);else applyUnavailable();document.querySelectorAll('.compare-card').forEach(node=>node.classList.toggle('active',node.dataset.method===s.method));document.documentElement.dataset.quoteApi='ready';window.dispatchEvent(new CustomEvent('woongbi:quote-ready',{detail:{state:s,pair,current}}));return{state:s,pair,current}}
function schedule(){clearTimeout(timer);timer=setTimeout(()=>{void sync().catch(()=>{applyUnavailable();document.documentElement.dataset.quoteApi='unavailable';window.dispatchEvent(new CustomEvent('woongbi:quote-unavailable',{detail:{state:currentState()}}))})},80)}
function status(){return{state:lastState,pair:lastPair,ready:document.documentElement.dataset.quoteApi==='ready',unavailable:document.documentElement.dataset.quoteApi==='unavailable'}}
window.WoongbiQuoteApi={state:currentState,get,getCurrent,fetchQuote,quotePair,sync:()=>sync().catch(()=>{applyUnavailable();document.documentElement.dataset.quoteApi='unavailable';window.dispatchEvent(new CustomEvent('woongbi:quote-unavailable',{detail:{state:currentState()}}));return null}),status,clear:()=>{cache.clear();pending.clear();lastPair={support:null,contract:null}}};
function init(){if(!$('device-select')||!$('plan-select'))return;ids.forEach(id=>$(id)?.addEventListener('change',schedule));$('device-search')?.addEventListener('input',schedule);window.dispatchEvent(new CustomEvent('woongbi:quote-api-loaded'));schedule()}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();
